<template><view class="page"><view class="custom-nav" :style="{ paddingTop: statusBarHeight + 'px' }"><view class="nav-row"><text class="nav-icon" @click="goBack">&#x2190;</text><text class="nav-title">&#x8D2A;&#x5403;&#x86C7;</text><text class="nav-icon" @click="resetGame">&#x1F504;</text></view></view><view class="content"><view class="score-bar"><text class="score">&#x5206;&#x6570;: {{ score }}</text><text class="best">&#x6700;&#x9AD8;: {{ bestScore }}</text></view><view class="game-board"><view class="cell" v-for="(cell, idx) in board" :key="idx" :class="{snake: cell===1, food: cell===2}"></view></view><view class="controls"><view class="ctrl-top"><view class="ctrl-btn" @click="setDir('up')">&#x2B06;</view></view><view class="ctrl-mid"><view class="ctrl-btn" @click="setDir('left')">&#x2B05;</view><view class="ctrl-btn" @click="setDir('right')">&#x27A1;</view></view><view class="ctrl-bottom"><view class="ctrl-btn" @click="setDir('down')">&#x2B07;</view></view></view><view v-if="gameOver" class="game-over"><text>&#x6E38;&#x620F;&#x7ED3;&#x675F;</text><view class="restart-btn" @click="resetGame"><text>&#x91CD;&#x65B0;&#x5F00;&#x59CB;</text></view></view></view></view></template><script setup>import { ref, onMounted, onUnmounted } from "vue"
const statusBarHeight = uni.getSystemInfoSync().statusBarHeight || 20
const GRID = 20
const board = ref(Array(GRID*GRID).fill(0))
const snake = ref([{x:10,y:10}])
const food = ref({x:5,y:5})
const dir = ref("right")
const score = ref(0)
const bestScore = ref(0)
const gameOver = ref(false)
var timer = null
function goBack() { uni.navigateBack(); clearInterval(timer) }
function resetGame() { clearInterval(timer); snake.value = [{x:10,y:10}]; dir.value = "right"; score.value = 0; gameOver.value = false; placeFood(); board.value = Array(GRID*GRID).fill(0); startGame() }
function startGame() { timer = setInterval(tick, 150) }
function placeFood() { var empty = []; for (var i = 0; i < GRID*GRID; i++) if (board.value[i] === 0) empty.push(i); if (empty.length) { var idx = empty[Math.floor(Math.random()*empty.length)]; food.value = {x: idx%GRID, y: Math.floor(idx/GRID)} } }
function tick() { var head = Object.assign({}, snake.value[0]); if (dir.value==="right") head.x++; else if (dir.value==="left") head.x--; else if (dir.value==="up") head.y--; else head.y++; if (head.x<0||head.x>=GRID||head.y<0||head.y>=GRID) { gameOver.value = true; clearInterval(timer); updateBest(); return } for (var i = 0; i < snake.value.length; i++) if (snake.value[i].x===head.x&&snake.value[i].y===head.y) { gameOver.value = true; clearInterval(timer); updateBest(); return } snake.value.unshift(head); if (head.x===food.value.x&&head.y===food.value.y) { score.value += 10; placeFood() } else { snake.value.pop() } renderBoard() }
function renderBoard() { var b = Array(GRID*GRID).fill(0); snake.value.forEach(function(s){b[s.y*GRID+s.x]=1}); b[food.value.y*GRID+food.value.x]=2; board.value = b }
function setDir(d) { if ((d==="up"&&dir.value==="down")||(d==="down"&&dir.value==="up")||(d==="left"&&dir.value==="right")||(d==="right"&&dir.value==="left")) return; dir.value = d }
function updateBest() { if (score.value > bestScore.value) { bestScore.value = score.value; uni.setStorageSync("snake_best", score.value) } }
onMounted(function() { if (!uni.getStorageSync("isLoggedIn")) { uni.reLaunch({ url: "/pages/login/login" }); return } bestScore.value = uni.getStorageSync("snake_best") || 0; renderBoard(); startGame() })
onUnmounted(function() { clearInterval(timer) })
</script><style scoped>.page{min-height:100vh;background:#f5f7fb}.custom-nav{background:linear-gradient(135deg,#22c55e,#16a34a);width:100%}.nav-row{height:88rpx;display:flex;align-items:center;padding:0 24rpx}.nav-icon{width:72rpx;text-align:center;font-size:44rpx;color:#fff;font-weight:700;flex-shrink:0}.nav-title{flex:1;text-align:center;font-size:32rpx;color:#fff;font-weight:600}.content{padding:24rpx}.score-bar{display:flex;justify-content:space-between;margin-bottom:16rpx}.score{font-size:28rpx;color:#22c55e;font-weight:700}.best{font-size:28rpx;color:#999}.game-board{display:grid;grid-template-columns:repeat(20,1fr);gap:1rpx;background:#d1fae5;border-radius:12rpx;padding:4rpx}.cell{width:100%;aspect-ratio:1;background:#f0fdf4;border-radius:2rpx}.cell.snake{background:linear-gradient(135deg,#22c55e,#16a34a)}.cell.food{background:#ef4444;border-radius:50%}.controls{margin-top:24rpx;display:flex;flex-direction:column;align-items:center;gap:8rpx}.ctrl-top,.ctrl-mid,.ctrl-bottom{display:flex;gap:16rpx}.ctrl-btn{width:100rpx;height:100rpx;background:#fff;border-radius:16rpx;display:flex;align-items:center;justify-content:center;font-size:40rpx;box-shadow:0 4rpx 16rpx rgba(0,0,0,.08)}.game-over{text-align:center;margin-top:24rpx}.game-over text{font-size:36rpx;color:#ef4444;font-weight:700}.restart-btn{background:linear-gradient(135deg,#22c55e,#16a34a);border-radius:16rpx;padding:24rpx;margin-top:16rpx}.restart-btn text{color:#fff;font-size:30rpx;font-weight:600}</style>